package claudecode

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// GenerateText sends a prompt to the Claude CLI and returns the raw text response.
// Implements the agent.TextGenerator interface.
// The model parameter hints which model to use (e.g., "haiku", "sonnet").
// If empty, defaults to "haiku" for fast, cheap generation.
//
// Unlike most agents, this implementation runs the subprocess directly rather
// than through agent.RunIsolatedTextGeneratorCLI. The shared helper collapses
// stderr + exit code into a single formatted error string, but Claude CLI
// returns operational errors (auth, rate limit, invalid model) as exit 0
// with is_error:true in the JSON envelope on stdout — so we need structured
// access to stdout, stderr and the exit code to produce the typed ClaudeError
// values that formatCheckpointSummaryError maps to actionable messages.
func (c *ClaudeCodeAgent) GenerateText(ctx context.Context, prompt string, model string) (string, error) {
	claudePath := "claude"
	if model == "" {
		model = "haiku"
	}

	commandRunner := c.CommandRunner
	if commandRunner == nil {
		commandRunner = exec.CommandContext
	}

	cmd := commandRunner(ctx, claudePath,
		"--print", "--output-format", "json",
		"--model", model, "--setting-sources", "")

	// Isolate from the user's git repo to prevent recursive hook triggers
	// and index pollution (matches agent.RunIsolatedTextGeneratorCLI behavior).
	cmd.Dir = os.TempDir()
	cmd.Env = agent.StripGitEnv(os.Environ())
	cmd.Stdin = strings.NewReader(prompt)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		// Prefer a structured Claude error over bare ctx sentinels: if the CLI
		// already emitted an is_error envelope on stdout, surface that even when
		// the context happens to be done. Otherwise the user loses actionable
		// auth/rate-limit/config diagnostics whenever ctx and the subprocess
		// both fail at roughly the same time.
		if _, env, parseErr := parseGenerateTextResponse(stdout.Bytes()); parseErr == nil && env != nil && env.IsError {
			result := ""
			if env.Result != nil {
				result = *env.Result
			}
			exitCode := 0
			var exitErr *exec.ExitError
			if errors.As(err, &exitErr) {
				exitCode = exitErr.ExitCode()
			}
			return "", classifyEnvelopeError(result, env.APIErrorStatus, exitCode)
		}
		// No structured signal on stdout — ctx cancellation is next most
		// informative, since the rest is a guess.
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			return "", context.DeadlineExceeded
		}
		if errors.Is(ctx.Err(), context.Canceled) {
			return "", context.Canceled
		}
		if isExecNotFound(err) {
			return "", &ClaudeError{Kind: ClaudeErrorCLIMissing, Cause: err}
		}
		exitCode := -1
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		}
		return "", classifyStderrError(stderr.String(), exitCode)
	}

	// Exit 0: parse the response and check for is_error (Claude CLI returns
	// most operational errors as exit 0 with is_error:true in the envelope).
	result, env, err := parseGenerateTextResponse(stdout.Bytes())
	if err != nil {
		return "", &ClaudeError{Kind: ClaudeErrorUnknown, Message: fmt.Sprintf("failed to parse claude CLI response: %v", err), Cause: err}
	}
	if env != nil && env.IsError {
		return "", classifyEnvelopeError(result, env.APIErrorStatus, 0)
	}

	return result, nil
}

// isExecNotFound returns true only when err indicates the binary was not
// found on PATH or at the given absolute path. It intentionally excludes
// other *exec.Error causes (permission denied, invalid executable format),
// which should surface as a generic failure so operators aren't misdirected
// to a reinstall when the real problem is a broken/inaccessible binary.
func isExecNotFound(err error) bool {
	var execErr *exec.Error
	if errors.As(err, &execErr) && errors.Is(execErr.Err, exec.ErrNotFound) {
		return true
	}
	return errors.Is(err, exec.ErrNotFound) || errors.Is(err, os.ErrNotExist)
}

	// Check if transcript exists
	if len(content.Transcript) == 0 {
		return fmt.Errorf("checkpoint %s has no transcript to summarize", checkpointID)
	}

	// Scope the transcript to only this checkpoint's portion
	scopedTranscript := scopeTranscriptForCheckpoint(content.Transcript, content.Metadata.GetTranscriptStart(), content.Metadata.Agent)
	if len(scopedTranscript) == 0 {
		return fmt.Errorf("checkpoint %s has no transcript content for this checkpoint (scoped)", checkpointID)
	}

	provider, err := resolveCheckpointSummaryProvider(ctx, w)
	if err != nil {
		return fmt.Errorf("failed to resolve summary provider: %w", err)
	}

	// Generate summary using shared helper
	logging.Info(ctx, "generating checkpoint summary")
	if errW != nil {
		fmt.Fprintln(errW, "Generating checkpoint summary...")
	}

	summary, appliedDeadline, err := generateCheckpointAISummary(ctx, scopedTranscript, cpSummary.FilesTouched, content.Metadata.Agent, provider.Generator)
	if err != nil {
		return formatCheckpointSummaryError(err, appliedDeadline)
	}

	// Persist to both stores; at least one must succeed.
	v1Err := v1Store.UpdateSummary(ctx, checkpointID, summary)
	var v2Err error
	if v2Store != nil {
		v2Err = v2Store.UpdateSummary(ctx, checkpointID, summary)
	}

	switch {
	case v1Err != nil && (v2Store == nil || v2Err != nil):
		// No store succeeded — hard error.
		if v2Err != nil {
			return fmt.Errorf("failed to save summary: v1: %w, v2: %w", v1Err, v2Err)
		}
		return fmt.Errorf("failed to save summary: %w", v1Err)
	case v1Err != nil:
		logging.Debug(ctx, "v1 UpdateSummary failed (v2 succeeded)",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("error", v1Err.Error()),
		)
	case v2Err != nil:
		logging.Debug(ctx, "v2 UpdateSummary failed (v1 succeeded)",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("error", v2Err.Error()),
		)
	}

	fmt.Fprintln(w, "✓ Summary generated and saved")
	fmt.Fprint(w, formatSummaryProviderDetails(provider))
	return nil
}

// generateCheckpointAISummary returns the generated summary, the effective
// deadline applied to the underlying call (which may be shorter than
// checkpointSummaryTimeout if the parent context had an earlier deadline),
// and any error. The effective deadline is returned so the caller can render
// the true timeout value in user-facing error messages instead of always
// showing the package default.
func generateCheckpointAISummary(ctx context.Context, scopedTranscript []byte, filesTouched []string, agentType types.AgentType, generator summarize.Generator) (*checkpoint.Summary, time.Duration, error) {
	timeoutCtx, cancel := context.WithTimeout(ctx, checkpointSummaryTimeout)
	timeoutDuration := checkpointSummaryTimeout
	if deadline, ok := timeoutCtx.Deadline(); ok {
		timeoutDuration = time.Until(deadline)
	}
	defer cancel()

	// scopedTranscript is read from checkpoint storage, which redacts on write.
	summary, err := generateTranscriptSummary(timeoutCtx, redact.AlreadyRedacted(scopedTranscript), filesTouched, agentType, generator)
	if err != nil {
		// Only classify as ctx cancel/deadline when the error chain actually
		// contains the sentinel. Relying on timeoutCtx.Err() here loses typed
		// errors (e.g. *ClaudeError) when the subprocess returned a real
		// structured failure while timeoutCtx.Err() is non-nil for any reason
		// (parent cancelled, deadline already elapsed, etc.).
		if errors.Is(err, context.Canceled) {
			return nil, timeoutDuration, fmt.Errorf("summary generation canceled: %w", err)
		}
		if errors.Is(err, context.DeadlineExceeded) {
			return nil, timeoutDuration, fmt.Errorf("summary generation timed out after %s: %w", formatSummaryTimeout(timeoutDuration), err)
		}
		return nil, timeoutDuration, err
	}

	return summary, timeoutDuration, nil
}

// formatCheckpointSummaryError maps typed Claude CLI errors and context
// sentinels to user-facing messages.
func formatCheckpointSummaryError(err error, deadline time.Duration) error {
	var claudeErr *claudecode.ClaudeError
	switch {
	case errors.As(err, &claudeErr):
		switch claudeErr.Kind { //nolint:exhaustive // ClaudeErrorUnknown handled by default
		case claudecode.ClaudeErrorAuth:
			return fmt.Errorf("Claude authentication failed%s\nRun `claude login` and retry", formatMessageSuffix(claudeErr.Message)) //nolint:staticcheck // ST1005: capitalized because Claude is a proper noun
		case claudecode.ClaudeErrorRateLimit:
			return fmt.Errorf("Claude rejected the summary request due to rate limits or quota%s\nWait and retry", formatMessageSuffix(claudeErr.Message)) //nolint:staticcheck // ST1005
		case claudecode.ClaudeErrorConfig:
			return fmt.Errorf("Claude rejected the summary request%s\nCheck your Claude CLI config and selected model", formatMessageSuffix(claudeErr.Message)) //nolint:staticcheck // ST1005
		case claudecode.ClaudeErrorCLIMissing:
			return errors.New("Claude CLI is not installed or not on PATH") //nolint:staticcheck // ST1005
		default:
			return fmt.Errorf("Claude failed to generate the summary%s", formatClaudeErrorSuffix(claudeErr)) //nolint:staticcheck // ST1005
		}
	case errors.Is(err, context.DeadlineExceeded):
		// Deliberately provider-neutral: explain --generate supports multiple
		// summary providers (claude-code, codex, gemini, ...), so hardcoding
		// "Claude" / "sonnet" / "Anthropic" here would misdirect users who
		// selected a different provider in .entire/settings.json.
		return fmt.Errorf(
			"summary generation did not return within the %s safety deadline. This usually means one of:\n"+
				"  - the selected model is taking longer than expected on a large transcript\n"+
				"  - the summary provider's CLI cannot reach its API (network, VPN, firewall)\n"+
				"    Try: run the provider CLI directly to confirm it works\n"+
				"  - the provider's API is degraded",
			formatSummaryTimeout(deadline))
	case errors.Is(err, context.Canceled):
		return errors.New("summary generation canceled")
	default:
		return fmt.Errorf("failed to generate summary: %w", err)
	}
}

// formatMessageSuffix formats ": <msg>" when msg is non-empty and "" otherwise.
// Used by the Auth / RateLimit / Config branches of formatCheckpointSummaryError
// to avoid rendering a bare colon when ClaudeError.Message is empty (reachable
// when the CLI envelope is is_error:true with result:null but a real status).
func formatMessageSuffix(msg string) string {
	if msg == "" {
		return ""
	}
	return ": " + msg
}

// formatClaudeErrorSuffix builds a diagnostic suffix for user-facing output
// when we fall through to the default "failed to generate the summary" path.
// Prefers the envelope Message, falls back to HTTP status, then exit code,
// so the user never sees a bare "Claude failed to generate the summary:"
// with nothing after the colon (which happens when Claude returns
// is_error:true with result:null, or when the subprocess crashes with no
// stderr output). ExitCode < 0 means the subprocess did not produce a real
// exit code (e.g. launch failure) — render that as "abnormal termination"
// rather than the misleading "exited with code -1".
func formatClaudeErrorSuffix(e *claudecode.ClaudeError) string {
	if e.Message != "" {
		return ": " + e.Message
	}
	switch {
	case e.APIStatus != 0:
		return fmt.Sprintf(" (Anthropic API returned HTTP %d)", e.APIStatus)
	case e.ExitCode > 0:
		return fmt.Sprintf(" (claude CLI exited with code %d)", e.ExitCode)
	case e.ExitCode < 0:
		return " (claude CLI terminated abnormally — no exit code captured)"
	default:
		return " (no diagnostic detail available from Claude CLI)"
	}
}

func formatSummaryTimeout(d time.Duration) string {
	if d < 0 {
		d = 0
	}
	if d < time.Second {
		return d.Round(10 * time.Millisecond).String()
	}
	return d.Round(time.Second).String()
}

// explainTemporaryCheckpoint finds and formats a temporary checkpoint by shadow commit hash prefix.
// Returns the formatted output and whether the checkpoint was found.
// Searches ALL shadow branches, not just the one for current HEAD, to find checkpoints
// created from different base commits (e.g., if HEAD advanced since session start).
// The writer w is used for raw transcript output to bypass the pager.
func explainTemporaryCheckpoint(ctx context.Context, w io.Writer, repo *git.Repository, store *checkpoint.GitStore, shaPrefix string, verbose, full, rawTranscript bool) (string, bool) {
	// List temporary checkpoints from ALL shadow branches
	// This ensures we find checkpoints even if HEAD has advanced since the session started
	tempCheckpoints, err := store.ListAllTemporaryCheckpoints(ctx, "", branchCheckpointsLimit)
	if err != nil {
		return "", false
	}

	// Find checkpoints matching the SHA prefix - check for ambiguity
	var matches []checkpoint.TemporaryCheckpointInfo
	for _, tc := range tempCheckpoints {
		if strings.HasPrefix(tc.CommitHash.String(), shaPrefix) {
			matches = append(matches, tc)
		}
	}

	if len(matches) == 0 {
		return "", false
	}

package claudecode

import (
	"fmt"
	"strings"
)

// ClaudeErrorKind classifies a typed Claude CLI error so callers can
// produce actionable user-facing messages without parsing strings.
type ClaudeErrorKind string

const (
	// ClaudeErrorAuth indicates an authentication or authorization failure
	// (HTTP 401/403 in the CLI envelope, or recognized stderr substring).
	ClaudeErrorAuth ClaudeErrorKind = "auth"
	// ClaudeErrorRateLimit indicates the request was rejected for rate-limit
	// or quota reasons (HTTP 429).
	ClaudeErrorRateLimit ClaudeErrorKind = "rate_limit"
	// ClaudeErrorConfig indicates a client-side request error other than
	// auth or rate-limit (e.g., HTTP 4xx for invalid model or malformed args).
	ClaudeErrorConfig ClaudeErrorKind = "config"
	// ClaudeErrorCLIMissing indicates the claude binary was not found on PATH.
	ClaudeErrorCLIMissing ClaudeErrorKind = "cli_missing"
	// ClaudeErrorUnknown is the catch-all for failures we cannot classify.
	ClaudeErrorUnknown ClaudeErrorKind = "unknown"
)

// ClaudeError is a typed error returned by ClaudeCodeAgent's text generation
// methods. APIStatus and ExitCode use zero to mean "not applicable."
type ClaudeError struct {
	Kind      ClaudeErrorKind
	Message   string // user-safe text extracted from the CLI envelope or stderr
	APIStatus int
	ExitCode  int
	Cause     error
}

func (e *ClaudeError) Error() string {
	if e.Message == "" {
		if e.ExitCode != 0 {
			return fmt.Sprintf("claude CLI error (kind=%s, exit=%d)", e.Kind, e.ExitCode)
		}
		return fmt.Sprintf("claude CLI error (kind=%s)", e.Kind)
	}
	return fmt.Sprintf("claude CLI error (kind=%s): %s", e.Kind, e.Message)
}

func (e *ClaudeError) Unwrap() error { return e.Cause }

const stderrMessageMaxLen = 500

// authStderrPhrases is intentionally small. The primary auth-detection path
// is the structured envelope (classifyEnvelopeError); these phrases are a
// best-effort fallback for crashes that exit non-zero before the envelope
// is produced.
var authStderrPhrases = []string{
	"invalid api key",
	"not logged in",
}

// classifyEnvelopeError converts a Claude CLI is_error:true envelope into a
// typed ClaudeError. The result text is treated as user-safe (the CLI
// produces it for human consumption).
func classifyEnvelopeError(resultText string, apiStatus *int, exitCode int) *ClaudeError {
	e := &ClaudeError{
		Message:  resultText,
		ExitCode: exitCode,
	}
	if apiStatus != nil {
		e.APIStatus = *apiStatus
	}
	switch {
	case e.APIStatus == 401, e.APIStatus == 403:
		e.Kind = ClaudeErrorAuth
	case e.APIStatus == 429:
		e.Kind = ClaudeErrorRateLimit
	case e.APIStatus >= 400 && e.APIStatus < 500:
		e.Kind = ClaudeErrorConfig
	case e.APIStatus == 0 && hasAuthPhrase(resultText):
		// No structured status (older CLI builds / internal errors) — fall
		// back to the same phrase heuristic the stderr path uses so users
		// still get auth-specific guidance.
		e.Kind = ClaudeErrorAuth
	default:
		e.Kind = ClaudeErrorUnknown
	}
	return e
}

// classifyStderrError is a fallback classifier used when the subprocess exited
// non-zero without producing a parseable envelope. It only attempts to
// recognize a small, stable set of auth phrases; everything else becomes
// ClaudeErrorUnknown with the (truncated) stderr as the message.
func classifyStderrError(stderr string, exitCode int) *ClaudeError {
	msg := strings.TrimSpace(stderr)
	if len(msg) > stderrMessageMaxLen {
		msg = msg[:stderrMessageMaxLen]
	}
	e := &ClaudeError{Message: msg, ExitCode: exitCode}
	if hasAuthPhrase(msg) {
		e.Kind = ClaudeErrorAuth
		return e
	}
	e.Kind = ClaudeErrorUnknown
	return e
}

func hasAuthPhrase(s string) bool {
	lower := strings.ToLower(s)
	for _, phrase := range authStderrPhrases {
		if strings.Contains(lower, phrase) {
			return true
		}
	}
	return false
}

