	if isExecNotFound(err) {
		return "", &ClaudeError{Kind: ClaudeErrorCLIMissing, Cause: err}
	}
	exitCode := -1
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		exitCode = exitErr.ExitCode()
	}
	// Prefer stderr, but some failures (broken/incompatible binary,
	// non-zero exits that print to stdout, partial envelopes that fail
	// the IsError gate above) leave stderr empty. Fall back to stdout
	// then to the exec error itself so the user always gets actionable
	// detail instead of "no diagnostic detail available".
	diag := strings.TrimSpace(stderr.String())
	if diag == "" {
		diag = strings.TrimSpace(stdout.String())
	}
	if diag == "" {
		diag = err.Error()
	}
	return "", classifyStderrError(diag, exitCode)
}
